SHOLD DECIMAL(18,2), \" +\n                        \"TIER_APR DECIMAL(18,10), \" +\n                        \"CURRENCY VARCHAR(8), \" +\n                        \"FEE_PLAN VARCHAR(32)\" +\n                        \")\");\n\n                st.execute(\"CREATE TABLE TXNS (\" +\n                        \"ROW_NUM INT PRIMARY KEY, \" +\n                        \"TX_ID VARCHAR(64), \" +\n                        \"ACCOUNT_ID VARCHAR(32), \" +\n                        \"EFFECTIVE_DATE DATE, \" +\n                        \"AMOUNT DECIMAL(18,2), \" +\n                        \"CURRENCY VARCHAR(8), \" +\n                        \"STATUS VARCHAR(32), \" +\n                        \"REVERSAL_OF VARCHAR(64)\" +\n                        \")\");\n\n                st.execute(\"CREATE TABLE RUN_AUDIT (\" +\n                        \"JDBC_URL VARCHAR(2000), \" +\n                        \"BIZ_DATE DATE, \" +\n                        \"ACCOUNTS INT, \" +\n                        \"VALID_TXS INT, \" +\n                        \"SKIPPED_TXS INT, \" +\n                        \"REPORT_MD5 VARCHAR(64)\" +\n                        \")\");\n\n            } finally {\n                st.close();\n            }\n\n            PreparedStatement psA = c.prepareStatement(\n                    \"INSERT INTO ACCOUNTS (ACCOUNT_ID, OPENED_AT, START_BALANCE, BASE_APR, PROMO_APR, PROMO_DAYS, TIER_THRESHOLD, TIER_APR, CURRENCY, FEE_PLAN) VALUES (?,?,?,?,?,?,?,?,?,?)\");\n            try {\n                for (Account a : accounts.values()) {\n                    psA.setString(1, a.accountId);\n                    psA.setDate(2, java.sql.Date.valueOf(a.openedAt));\n                    psA.setBigDecimal(3, a.startBalance);\n                    psA.setBigDecimal(4, a.baseApr);\n                    psA.setBigDecimal(5, a.promoApr);\n                    psA.setInt(6, a.promoDays);\n                    psA.setBigDecimal(7, a.tierThreshold);\n                    psA.setBigDecimal(8, a.tierApr);\n                    psA.setString(9, a.currency);\n                    psA.setString(10, a.feePlan);\n                    psA.executeUpdate();\n                }\n            } finally {\n                psA.close();\n            }\n\n            PreparedStatement psT = c.prepareStatement(\n                    \"INSERT INTO TXNS (ROW_NUM, TX_ID, ACCOUNT_ID, EFFECTIVE_DATE, AMOUNT, CURRENCY, STATUS, REVERSAL_OF) VALUES (?,?,?,?,?,?,?,?)\");\n            try {\n                for (Txn t : txns) {\n                    psT.setInt(1, t.rowNum);\n                    psT.setString(2, t.txId);\n                    psT.setString(3, t.accountId);\n                    psT.setDate(4, java.sql.Date.valueOf(t.effectiveDate));\n                    psT.setBigDecimal(5, t.amount);\n                    psT.setString(6, t.currency);\n                    psT.setString(7, t.status);\n                    psT.setString(8, (t.reversalOf == null) ? \"\" : t.reversalOf);\n                    psT.executeUpdate();\n                }\n            } finally {\n                psT.close();\n            }\n        } finally {\n            c.close();\n        }\n    }\n\n    private static void insertRunAudit(String bizDate, int accounts, int validTxs, int skippedTxs, String reportMd5) throws Exception {\n        Connection c = DriverManager.getConnection(JDBC_URL, \"sa\", \"\");\n        try {\n            Statement st = c.createStatement();\n            try {\n                safeExecute(st, \"DELETE FROM RUN_AUDIT\");\n            } finally {\n                st.close();\n            }\n\n            PreparedStatement ps = c.prepareStatement(\n                    \"INSERT INTO RUN_AUDIT (JDBC_URL, BIZ_DATE, ACCOUNTS, VALID_TXS, SKIPPED_TXS, REPORT_MD5) VALUES (?,?,?,?,?,?)\");\n            try {\n                ps.setString(1, JDBC_URL);\n                ps.setDate(2, java.sql.Date.valueOf(bizDate));\n                ps.setInt(3, accounts);\n                ps.setInt(4, validTxs);\n                ps.setInt(5, skippedTxs);\n                ps.setString(6, reportMd5);\n                ps.executeUpdate();\n            } finally {\n                ps.close();\n            }\n        } finally {\n            c.close();\n        }\n    }\n\n    private static void safeExecute(Statement st, String sql) {\n        try {\n            st.execute(sql);\n        } catch (SQLException ignored) {\n        }\n    }\n\n    private static String readFirstLine(File f) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(new FileInputStream(f), UTF8));\n        try {\n            String s = br.readLine();\n            if (s == null) return \"\";\n            return s;\n        } finally {\n            br.close();\n        }\n    }\n\n    private static BigDecimal bd(String s) {\n        return new BigDecimal(s);\n    }\n\n    // yyyy-MM-dd -> day number using UTC to avoid DST surprises\n    private static int parseDay(String yyyyMmDd) {\n        try {\n            SimpleDateFormat sdf = new SimpleDateFormat(\"yyyy-MM-dd\");\n            sdf.setLenient(false);\n            sdf.setTimeZone(TimeZone.getTimeZone(\"UTC\"));\n            Date d = sdf.parse(yyyyMmDd);\n            long ms = d.getTime();\n            return (int) (ms / 86400000L);\n        } catch (ParseException e) {\n            throw new RuntimeException(\"Bad date: \" + yyyyMmDd, e);\n        }\n    }\n\n    private static String[] splitCsv(String line) {\n        // Inputs are simple (no quoted commas)\n        return line.split(\",\", -1);\n    }\n\n    private static class Account {\n        String accountId;\n        String openedAt;\n        int openedDay;\n        BigDecimal startBalance;\n        BigDecimal baseApr;\n        BigDecimal promoApr;\n        int promoDays;\n        BigDecimal tierThreshold;\n        BigDecimal tierApr;\n        String currency;\n        String feePlan;\n    }\n\n    private static class Txn {\n        int rowNum;\n        String txId;\n        String accountId;\n        String effectiveDate;\n        int effectiveDay;\n        BigDecimal amount;\n        String currency;\n        String status;\n        String reversalOf;\n    }\n\n    private static class FeeRule {\n        String feePlan;\n        String appliesTo;\n        BigDecimal flatFee;\n        BigDecimal pctFee;\n        BigDecimal minFee;\n        BigDecimal maxFee;\n    }\n\n    private static class ExceptionRow {\n        int rowNum;\n        String txId;\n        String reason;\n        ExceptionRow(int rowNum, String txId, String reason) {\n            this.rowNum = rowNum;\n            this.txId = txId;\n            this.reason = reason;\n        }\n    }\n\n    private static class InterestAndTotals {\n        byte[] interestCsvBytes;\n        BigDecimal totalInterest2dp;\n    }\n\n    private static class FxBook {\n        // key: from|to -> list of (rateDay, rate)\n        private final HashMap<String, ArrayList<FxRate>> rates = new HashMap<String, ArrayList<FxRate>>();\n\n        void add(int rateDay, String from, String to, BigDecimal rate) {\n            String k = key(from, to);\n            ArrayList<FxRate> lst = rates.get(k);\n            if (lst == null) {\n                lst = new ArrayList<FxRate>();\n                rates.put(k, lst);\n            }\n            FxRate r = new FxRate();\n            r.rateDay = rateDay;\n            r.rate = rate;\n            lst.add(r);\n        }\n\n        BigDecimal resolveRate(String from, String to, int effectiveDay, List<String> pivots) {\n            if (from.equals(to)) return BigDecimal.ONE.setScale(10, HALF_EVEN);\n\n            // direct and reverse candidates\n            RatePick direct = pickLatest(from, to, effectiveDay);\n            RatePick reverse = pickLatest(to, from, effectiveDay);\n\n            if (direct != null && reverse != null) {\n                if (direct.rateDay > reverse.rateDay) {\n                    return direct.rate.setScale(10, HALF_EVEN);\n           